create function pg_temp.sign(s jsonb) returns jsonb language sql as $$
 select s || jsonb_build_object('snapshot_checksum',atlas_legacy.master_snapshot_hash(s-'snapshot_checksum'))
$$;
select is(atlas_legacy.master_snapshot_hash(pg_temp.fixture()-'snapshot_checksum'),pg_temp.fixture()->>'snapshot_checksum','PostgreSQL canonical hash matches independently generated Node fixture');
select ok(not has_function_privilege('anon','atlas_legacy.apply_master_data_snapshot(jsonb,text,uuid)','EXECUTE'),'anon cannot apply');
select ok(not has_function_privilege('authenticated','atlas_legacy.preview_master_data_snapshot(jsonb)','EXECUTE'),'browser cannot preview private import');
select ok(not has_function_privilege('service_role','atlas_legacy.apply_master_data_snapshot(jsonb,text,uuid)','EXECUTE'),'service role cannot invoke private apply');
