 '{records,supplier_eligibilities}',pg_temp.fixture()#>'{records,supplier_eligibilities}' || '[{"legacy_id":"ingredient:1:supplier:13","ingredient_legacy_id":"1","supplier_legacy_id":"13","priority":2}]'::jsonb));
